quartz/styles/custom/a11y.scss.text:
// Accessibility. Loaded last so these rules win by order.

/* ------------------------------------------------------------------ target sizes */

// Touch screens: small links get at least 24px height (WCAG 2.5.8).
@media (pointer: coarse) {
  .breadcrumb-element a,
  a.nav-file-title,
  .folder-title,
  .toc-content a,
  footer a,
  .tag-link {
    min-height: 24px;
    display: inline-flex;
    align-items: center;
  }
}

/* --------------------------------------------------------------- screen readers */

// Hidden visually, still read by screen readers.
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* -------------------------------------------------------------- forced colours */

// High-contrast mode drops backgrounds: give filled surfaces a border, states an outline.
@media (forced-colors: active) {
  .callout,
  .layout-box-cta,
  .layout-box-note,
  .note-properties,
  .graph-outer,
  pre {
    border: 1px solid CanvasText;
  }

  .explorer a.active,
  .toc-content a.in-view,
  .result-card:hover,
  .result-card.focus {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }

  svg {
    forced-color-adjust: auto;
  }
}

/* ------------------------------------------------------------------ transparency */

@media (prefers-reduced-transparency: reduce) {
  .search-container,
  .global-graph-outer {
    backdrop-filter: none;
    background: var(--light);
  }
}

/* ------------------------------------------------------------------------- print */

// Print: content only, no sidebars or controls.
@media print {
  // .sidebar for Quartz's frames, .qgframe-area-* for authored ones.
  .sidebar,
  .qgframe-area-left,
  .qgframe-area-right,
  .explorer,
  .toc,
  .graph,
  .backlinks,
  .recent-notes,
  .search,
  .darkmode,
  .readermode,
  .layout-box-cta,
  .layout-box-hint,
  .clipboard-button {
    display: none !important;
  }

  .page,
  #quartz-body,
  .qgframe-grid {
    display: block !important;
    max-width: none !important;
    padding: 0 !important;
  }

  article > * {
    max-width: none;
  }

  // Fixed ink colours: print has no dark mode.

  // Write out link targets.
  article a[href^="http"]::after {
    content: " (" attr(href) ")";
    font-size: 0.85em;
    color: #555;
    word-break: break-all;
  }

  pre,
  .callout,
  blockquote {
    break-inside: avoid;
    border: 1px solid #999;
    background: none;
  }

  h1, h2, h3, h4, h5, h6 {
    break-after: avoid;
  }
}

